#!/usr/bin/env python3
"""Generate the final HTML report from computed chart data and stats."""

import json
from datetime import datetime

# Load computed data
with open("/app/output/chart_data.json") as f:
    cd = json.load(f)

with open("/app/output/stats.json") as f:
    s = json.load(f)

def js(arr):
    """Convert Python list to JS array literal."""
    if arr is None:
        return "null"
    return json.dumps(arr)

# Build the HTML report
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Fuel Price Trends & Policy Impact Analysis (2020–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #f8f9fa;
    --card-bg: #ffffff;
    --text: #1a1a2e;
    --text-secondary: #555;
    --accent: #1e5f74;
    --accent2: #f4a261;
    --accent3: #e76f51;
    --accent4: #2a9d8f;
    --border: #e0e0e0;
    --kpi-bg: #f0f4f8;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 15px;
  }}

  /* ── Hero ── */
  .hero {{
    background: linear-gradient(135deg, #0d1b2a 0%, #1b2838 50%, #1e5f74 100%);
    color: #fff;
    padding: 60px 40px 50px;
    text-align: center;
  }}
  .hero h1 {{ font-size: 2.2rem; font-weight: 700; max-width: 900px; margin: 0 auto 12px; letter-spacing: -0.5px; }}
  .hero .subtitle {{ font-size: 1.05rem; opacity: 0.85; max-width: 750px; margin: 0 auto 24px; }}
  .hero .meta {{ font-size: 0.82rem; opacity: 0.6; }}
  .hero .meta span {{ margin: 0 12px; }}

  /* ── Layout ── */
  .container {{ max-width: 1200px; margin: 0 auto; padding: 32px 24px; }}

  /* ── KPI Cards ── */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 40px;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 22px 20px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
    border-left: 4px solid var(--accent);
    text-align: center;
  }}
  .kpi-card .label {{ font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.6px; color: var(--text-secondary); margin-bottom: 6px; }}
  .kpi-card .value {{ font-size: 1.8rem; font-weight: 700; color: var(--accent); }}
  .kpi-card .unit {{ font-size: 0.85rem; color: var(--text-secondary); }}

  /* ── Sections ── */
  .section {{
    background: var(--card-bg);
    border-radius: 12px;
    padding: 36px 32px;
    margin-bottom: 32px;
    box-shadow: 0 1px 6px rgba(0,0,0,0.05);
  }}
  .section h2 {{
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--accent);
    margin-bottom: 8px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--border);
  }}
  .section h3 {{
    font-size: 1.15rem;
    font-weight: 600;
    color: #2c3e50;
    margin: 28px 0 12px;
  }}
  .section p {{ margin-bottom: 14px; color: #333; }}
  .section .objective {{
    font-size: 0.9rem;
    color: var(--text-secondary);
    font-style: italic;
    margin-bottom: 24px;
  }}

  /* ── Charts ── */
  .chart-wrap {{
    position: relative;
    width: 100%;
    margin: 24px 0;
  }}
  .chart-wrap canvas {{ width: 100% !important; }}

  /* ── Tables ── */
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0 24px;
    font-size: 0.9rem;
  }}
  thead th {{
    background: #1e5f74;
    color: #fff;
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
  }}
  tbody td {{
    padding: 9px 12px;
    border-bottom: 1px solid var(--border);
  }}
  tbody tr:nth-child(even) {{ background: #f7f9fb; }}
  tbody tr:hover {{ background: #e8f0f6; }}
  .num {{ text-align: right; font-variant-numeric: tabular-nums; }}

  /* ── Callouts ── */
  .callout {{
    background: #e8f4f8;
    border-left: 4px solid var(--accent4);
    border-radius: 6px;
    padding: 16px 20px;
    margin: 20px 0;
    font-size: 0.92rem;
  }}
  .callout strong {{ color: var(--accent); }}

  .callout-warn {{
    background: #fef3e2;
    border-left-color: var(--accent2);
  }}

  /* ── Findings ── */
  .finding-list {{ counter-reset: finding; list-style: none; padding: 0; }}
  .finding-list li {{
    counter-increment: finding;
    padding: 14px 16px 14px 52px;
    margin: 10px 0;
    background: #f7f9fb;
    border-radius: 8px;
    position: relative;
    font-size: 0.94rem;
  }}
  .finding-list li::before {{
    content: counter(finding);
    position: absolute;
    left: 14px;
    top: 14px;
    width: 26px;
    height: 26px;
    background: var(--accent);
    color: #fff;
    border-radius: 50%;
    text-align: center;
    line-height: 26px;
    font-weight: 700;
    font-size: 0.82rem;
  }}

  /* ── Subsidy comparison grid ── */
  .compare-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin: 20px 0;
  }}
  .compare-card {{
    padding: 20px;
    border-radius: 10px;
    text-align: center;
  }}
  .compare-card.high-sub {{ background: #e8f5e9; border: 1px solid #a5d6a7; }}
  .compare-card.low-sub {{ background: #fbe9e7; border: 1px solid #ef9a9a; }}
  .compare-card h4 {{ font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }}
  .compare-card .big {{ font-size: 2rem; font-weight: 700; }}
  .high-sub .big {{ color: #2e7d32; }}
  .low-sub .big {{ color: #c62828; }}

  /* ── Footer ── */
  .footer {{
    text-align: center;
    padding: 30px;
    color: var(--text-secondary);
    font-size: 0.82rem;
    border-top: 1px solid var(--border);
    margin-top: 20px;
  }}

  @media (max-width: 768px) {{
    .hero h1 {{ font-size: 1.5rem; }}
    .kpi-grid {{ grid-template-columns: 1fr 1fr; }}
    .compare-grid {{ grid-template-columns: 1fr; }}
    .section {{ padding: 20px 16px; }}
  }}
</style>
</head>
<body>

<!-- ═══════════ HERO ═══════════ -->
<header class="hero">
  <h1>Global Fuel Price Trends &amp; Policy Impact Analysis (2020–2026)</h1>
  <p class="subtitle">A comprehensive trend analysis of retail fuel prices across 84 countries, examining the interplay between Brent Crude benchmarks, taxation, subsidies, and regional economic conditions over a six-year period.</p>
