    petrol_avg=("petrol_usd_liter", "mean"),
    diesel_avg=("diesel_usd_liter", "mean"),
    lpg_avg=("lpg_usd_liter", "mean"),
    petrol_std=("petrol_usd_liter", "std"),
    avg_tax=("tax_percentage", "mean"),
    country_count=("country", "nunique"),
).reset_index().sort_values(["subsidy_level", "income_level"])

subsidy_income_rows = ""
subsidy_order = ["Very High", "High", "Medium", "Low"]
income_order = ["High", "Middle", "Low"]
for sub in subsidy_order:
    for inc in income_order:
        mask = (subsidy_income["subsidy_level"] == sub) & (subsidy_income["income_level"] == inc)
        row = subsidy_income[mask]
        if len(row) == 0:
            continue
        r = row.iloc[0]
        subsidy_income_rows += f"""      <tr><td>{sub}</td><td>{inc}</td><td class="num">{int(r['country_count'])}</td><td class="num">${r['petrol_avg']:.3f}</td><td class="num">${r['diesel_avg']:.3f}</td><td class="num">${r['lpg_avg']:.3f}</td><td class="num">{r['avg_tax']:.1f}%</td></tr>\n"""

# ── Income level table rows ──
income_avg = df.groupby("income_level").agg(
    petrol_avg=("petrol_usd_liter", "mean"),
    diesel_avg=("diesel_usd_liter", "mean"),
    lpg_avg=("lpg_usd_liter", "mean"),
    petrol_std=("petrol_usd_liter", "std"),
    avg_tax=("tax_percentage", "mean"),
).reset_index()

income_rows = ""
for _, r in income_avg.iterrows():
    cv = r["petrol_std"] / r["petrol_avg"] * 100
    income_rows += f"""      <tr><td>{r['income_level']}</td><td class="num">${r['petrol_avg']:.3f}</td><td class="num">${r['diesel_avg']:.3f}</td><td class="num">${r['lpg_avg']:.3f}</td><td class="num">{r['avg_tax']:.1f}%</td><td class="num">${r['petrol_std']:.3f}</td><td class="num">{cv:.1f}%</td></tr>\n"""

# ── Yearly table rows ──
yearly = df.groupby(df["date"].dt.year).agg(
    petrol_avg=("petrol_usd_liter", "mean"),
    diesel_avg=("diesel_usd_liter", "mean"),
    lpg_avg=("lpg_usd_liter", "mean"),
    brent_avg=("brent_crude_usd", "mean"),
    tax_avg=("tax_percentage", "mean"),
).reset_index().rename(columns={"date": "year"})

yearly_rows = ""
for _, r in yearly.iterrows():
    yearly_rows += f"""      <tr><td>{int(r['year'])}</td><td class="num">${r['petrol_avg']:.3f}</td><td class="num">${r['diesel_avg']:.3f}</td><td class="num">${r['lpg_avg']:.3f}</td><td class="num">${r['brent_avg']:.2f}</td><td class="num">{r['tax_avg']:.1f}%</td></tr>\n"""

