).reset_index().sort_values("petrol_avg", ascending=False)

region_rows = ""
for _, r in region_avg.iterrows():
    region_rows += f"""      <tr><td>{r['region']}</td><td class="num">${r['petrol_avg']:.3f}</td><td class="num">${r['diesel_avg']:.3f}</td><td class="num">${r['lpg_avg']:.3f}</td><td class="num">{r['avg_tax']:.1f}%</td></tr>\n"""

# ── Correlation table rows ──
corr_rows = f"""      <tr><td>Petrol</td><td class="num">{s['corr_petrol_brent']:.4f}</td><td class="num">{s['corr_petrol_brent']**2:.4f}</td><td>Near-perfect linear relationship</td></tr>
