# ── Subsidy pass-through table ──
pass_through_rows = f"""      <tr><td>High</td><td class="num">{s['corr_high_petrol_brent']:.4f}</td><td class="num">{s['corr_high_diesel_brent']:.4f}</td><td>Near-complete pass-through</td></tr>
