# ── Date range labels ──
date_min = str(df["date"].min().date())
date_max = str(df["date"].max().date())
total_rows = len(df)
total_countries = df["country"].nunique()

# ── Regional spread direction ──
spread_direction = "widened" if s['latest_spread'] > 2.5 else "narrowed"

# ── Price multiple ──
price_multiple = s['highest_region_petrol'] / s['lowest_region_petrol'] if s['lowest_region_petrol'] > 0 else 0
tax_multiple = s['tax_high_income'] / s['tax_low_income'] if s['tax_low_income'] > 0 else 0

